record.content:
\begin{definition}
A finite quantum group $Q_{Gf}$ is a pair $(\mathbb{H},\Phi)$ of a finite-dimensional \\
$C^*$-algebra $\mathbb{H}$ with a comultiplication $ \Phi$ such that $(\mathbb{H},\Phi)$ is a Hopf  $^*$-algebra.
\end{definition}



\begin{thebibliography}{9}
\bibitem{Abe1977}
ABE, E., {\em Hopf Algebras}, Cambridge University Press, 1977.

\bibitem{SME1969}
SWEEDLER, M.E., {\em Hopf Algebras}, W.A. Benjamin, inc., New York, 1969.

\bibitem{KJVD1997}
KUSTERMANS, J., VAN DAELE, A., C*-algebraic Quantum Groups arising from
Algebraic Quantum Groups, {\em Int. J. of Math.} 8 (1997), 1067-1139.


\bibitem{LEC1994}
LANCE, E.C., An explicit description of the fundamental unitary for $SU(2)_q$, 
{\em Commun. Math. Phys.} 164 (1994), 1-15.


\end{thebibliography}
